   310→  /**
   311→   * Handle a parsed JSON-RPC message
   312→   */
   313→  private handleMessage(message: unknown): void {
   314→    if (isResponse(message)) {
   315→      this.handleResponse(message);
   316→    } else if (isError(message)) {
   317→      this.handleErrorResponse(message);
   318→    } else if (isRequest(message)) {
   319→      // Agent is sending us a request (e.g., tool call) - this proves it's alive
   320→      // Reset timeout timers for any pending requests
   321→      this.resetPendingTimers();
   322→      this.emit("request", message);
   323→    } else if (isNotification(message)) {
   324→      // Agent is sending us a notification - also proves it's alive
   325→      this.resetPendingTimers();
   326→      this.emit("notification", message);
   327→    } else {
   328→      // Invalid message
   329→      this.sendError(null, {
   330→        code: -32600,
   331→        message: "Invalid Request",
   332→        data: message,
   333→      });
   334→    }
   335→  }
