// SKILL CONTENT VALIDATION
// ============================================================

/**
 * Validate that skill meta entries have corresponding SKILL.md files.
 * AC: @skill-content-model ac-3 - missing content file reports validation error
 */
async function validateSkillContentFiles(
  ctx: KspecContext,
  skills: LoadedSkill[],
): Promise<SchemaValidationError[]> {
  const errors: SchemaValidationError[] = [];

  for (const skill of skills) {
    const contentPath = getSkillContentPath(ctx, skill.id);

    try {
      await fs.access(contentPath);
    } catch {
      // File doesn't exist - report validation error
      errors.push({
        file: skill._sourceFile || "kynetic.meta.yaml",
        path: `skills.${skill.id}`,
        message: `Skill '${skill.id}' is missing content file at ${contentPath}`,
      });
    }
  }

  return errors;
}

// ============================================================
// AUTOMATION VALIDATION
// ============================================================

/**
 * Check task automation status for warnings
 * AC: @task-automation-eligibility ac-21, ac-23
 */
function checkAutomationEligibility(
  tasks: LoadedTask[],
  index: ReferenceIndex,
): CompletenessWarning[] {
  const warnings: CompletenessWarning[] = [];

  for (const task of tasks) {
    const taskRef = task.slugs?.[0]
      ? `@${task.slugs[0]}`
      : `@${index.shortUlid(task._ulid)}`;

    // AC: @task-automation-eligibility ac-21
    // Warn if eligible but no spec_ref
    if (task.automation === "eligible" && !task.spec_ref) {
      warnings.push({
        type: "automation_eligible_no_spec",
        itemRef: taskRef,
        itemTitle: task.title,
        message: `Task ${taskRef} is automation: eligible but has no spec_ref - eligible tasks should have linked specs`,
      });
    }

    // AC: @task-automation-eligibility ac-23
    // Warn if eligible but spec_ref doesn't resolve
    if (task.automation === "eligible" && task.spec_ref) {
      const specResult = index.resolve(task.spec_ref);
      if (!specResult.ok) {
        warnings.push({
          type: "automation_eligible_no_spec",
          itemRef: taskRef,
          itemTitle: task.title,
          message: `Task ${taskRef} is automation: eligible but spec_ref ${task.spec_ref} cannot be resolved`,
        });
      }
    }
  }

  return warnings;
}

// ============================================================
// SKILL VALIDATION
// ============================================================

/**
 * Validate skill depends_on references
 * AC: @skill-validation ac-2 - broken depends_on ref reports warning
 */
function validateSkillDependsOn(
  skills: LoadedSkill[],
  index: ReferenceIndex,
): RefValidationWarning[] {
  const warnings: RefValidationWarning[] = [];

  for (const skill of skills) {
    if (!skill.depends_on || skill.depends_on.length === 0) {
      continue;
    }

    for (const depRef of skill.depends_on) {
      const result = index.resolve(depRef);
      if (!result.ok) {
        warnings.push({
          ref: depRef,
          sourceFile: skill._sourceFile,
          sourceUlid: skill._ulid,
          field: "depends_on",
          warning: "deprecated_target", // Reuse warning type for broken refs
          message: `Skill '${skill.id}' depends_on reference '${depRef}' cannot be resolved`,
        });
      } else {
        // Check that the resolved item is actually a skill (uses _type discriminant)
        if (!isSkill(result.item)) {
          warnings.push({
            ref: depRef,
            sourceFile: skill._sourceFile,
            sourceUlid: skill._ulid,
            field: "depends_on",
            warning: "deprecated_target",
            message: `Skill '${skill.id}' depends_on reference '${depRef}' points to non-skill item`,
          });
        }
      }
    }
  }

  return warnings;
}

/**
 * Find orphaned skill directories (directories with no corresponding meta entry)
 * AC: @skill-validation ac-3 - orphaned directory reports warning
 */
async function findOrphanedSkillDirectories(
  ctx: KspecContext,
  skills: LoadedSkill[],
): Promise<RefValidationWarning[]> {
  const warnings: RefValidationWarning[] = [];
  const skillsDir = path.join(ctx.specDir, "skills");

  try {
    // Check if skills directory exists
    await fs.access(skillsDir);

    // Read all directories in skills/
    const entries = await fs.readdir(skillsDir, { withFileTypes: true });
    const directories = entries.filter(entry => entry.isDirectory());

    // Build set of skill IDs from meta
    const skillIds = new Set(skills.map(s => s.id));

    // Find orphaned directories
    for (const dir of directories) {
      if (!skillIds.has(dir.name)) {
        warnings.push({
          ref: `@${dir.name}`,
          sourceFile: path.join(skillsDir, dir.name),
          field: "directory",
          warning: "deprecated_target", // Reuse warning type
          message: `Orphaned skill directory '${dir.name}' has no corresponding meta entry`,
        });
      }
    }
  } catch {
    // Skills directory doesn't exist - that's fine
  }

  return warnings;
}

// ============================================================
// MAIN VALIDATION
// ============================================================

/**
 * Run full validation on a kspec project
 */
export async function validate(
  ctx: KspecContext,
  options: ValidateOptions = {},
): Promise<ValidationResult> {
  // Default: run all checks
  const runSchema = options.schema !== false;
  const runRefs = options.refs !== false;
  const runOrphans = options.orphans !== false;
  const runCompleteness = options.completeness !== false;

  const result: ValidationResult = {
    valid: true,
    schemaErrors: [],
    refErrors: [],
    refWarnings: [],
    orphans: [],
    completenessWarnings: [],
    traitCycleErrors: [],
    stats: {
      filesChecked: 0,
      itemsChecked: 0,
      tasksChecked: 0,
    },
  };

  const allTasks: LoadedTask[] = [];
  const allItems: LoadedSpecItem[] = [];

  // Validate manifest
  if (ctx.manifestPath && runSchema) {
    const manifestErrors = await validateManifestFile(ctx.manifestPath);
    result.schemaErrors.push(...manifestErrors);
    result.stats.filesChecked++;
  }

  // Load items from manifest (traits, inline modules, etc.)
  if (ctx.manifest && ctx.manifestPath) {
    const manifestItems = extractItemsFromRaw(ctx.manifest, ctx.manifestPath);
    allItems.push(...manifestItems);
    result.stats.itemsChecked += manifestItems.length;
  }

  // Find and validate task files
  // Exclude test fixtures which have their own self-contained references
  const taskFiles = await findTaskFiles(ctx.rootDir);
  const specTaskFiles = await findTaskFiles(path.join(ctx.rootDir, "spec"));
  const allTaskFiles = [...new Set([...taskFiles, ...specTaskFiles])].filter(
    (f) => !f.includes("/fixtures/"),
  );

  for (const taskFile of allTaskFiles) {
    if (runSchema) {
      const taskErrors = await validateTasksFile(taskFile);
      result.schemaErrors.push(...taskErrors);
    }
    result.stats.filesChecked++;

    // Load tasks for ref validation
    try {
      const raw = await readYamlFile<unknown>(taskFile);
      let taskList: unknown[] = [];

      if (Array.isArray(raw)) {
        taskList = raw;
      } else if (raw && typeof raw === "object" && "tasks" in raw) {
        taskList = (raw as { tasks: unknown[] }).tasks || [];
      }

      for (const t of taskList) {
        const parsed = TaskSchema.safeParse(t);
        if (parsed.success) {
          allTasks.push({ ...parsed.data, _sourceFile: taskFile });
          result.stats.tasksChecked++;
        }
      }
    } catch {
      // Already reported in schema validation
    }
  }

  // Validate spec files (from includes)
  if (ctx.manifest && ctx.manifestPath) {
    const manifestDir = path.dirname(ctx.manifestPath);
    const includes = ctx.manifest.includes || [];

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        if (runSchema) {
          const specErrors = await validateSpecFile(filePath);
          result.schemaErrors.push(...specErrors);
        }
        result.stats.filesChecked++;

        // Load items for ref validation
        try {
          const items = await loadSpecFile(filePath);
          allItems.push(...items);
          result.stats.itemsChecked += items.length;
        } catch {
          // Already reported in schema validation
        }
      }
    }
  }

  // Load meta items for reference validation
  // AC: @agent-definitions ac-agent-3
  const metaCtx = await loadMetaContext(ctx);
  const allMetaItems = [
    ...metaCtx.agents,
    ...metaCtx.workflows,
    ...metaCtx.conventions,
    ...metaCtx.observations,
    ...metaCtx.skills, // Include skills for reference indexing
  ];

  // Load plans for reference validation
  // AC: @plan-validation ac-10
  const allPlans = await loadPlans(ctx);

  // Build reference index when any downstream check needs it.
  const needsRefIndex = runRefs || runOrphans || runCompleteness;
  if (
    needsRefIndex &&
    (allTasks.length > 0 ||
      allItems.length > 0 ||
      allMetaItems.length > 0 ||
      allPlans.length > 0)
  ) {
    const index = new ReferenceIndex(
      allTasks,
      allItems,
      allMetaItems,
      allPlans,
    );

    if (runRefs) {
      const refResult = validateRefs(index, allTasks, allItems);

      // AC: @config-validation ac-2 ac-3 — strict_refs controls error vs warning
      // When strictRefs is false, demote "not_found" ref errors to warnings
      if (options.strictRefs === false) {
        // Move not_found errors to warnings
        const notFoundErrors = refResult.errors.filter((e) => e.error === "not_found");
        const otherErrors = refResult.errors.filter((e) => e.error !== "not_found");

        result.refErrors = otherErrors;
        result.refWarnings = [
          ...refResult.warnings,
          ...notFoundErrors.map((e) => ({
            ref: e.ref,
            sourceFile: e.sourceFile,
            sourceUlid: e.sourceUlid,
            field: e.field,
            warning: "deprecated_target" as const, // Reuse existing warning type
            message: e.message,
          })),
        ];
      } else {
        // Default/strict behavior: not_found refs are errors
        result.refErrors = refResult.errors;
        result.refWarnings = refResult.warnings;
      }

      // AC: @skill-validation ac-2 - validate skill depends_on references
      const skillDependsOnWarnings = validateSkillDependsOn(metaCtx.skills, index);
      result.refWarnings.push(...skillDependsOnWarnings);

      // AC: @trait-edge-cases ac-2
      // Detect circular trait references
      result.traitCycleErrors = detectTraitCycles(allItems, index);
    }

    // Orphan detection
    if (runOrphans) {
      result.orphans = findOrphans(allTasks, allItems, index);
    }

    // Completeness validation
    // AC: @spec-completeness ac-1, ac-2, ac-3
    // AC: @trait-validation ac-3
    if (runCompleteness) {
      // Build trait index for trait AC coverage validation
      const traitIndex = new TraitIndex(allItems, index);
      const completenessWarnings = await checkCompleteness(
        allItems,
        index,
        ctx.rootDir,
        traitIndex,
      );

      // AC: @task-automation-eligibility ac-21, ac-23
      // Check automation eligibility warnings for tasks
      const automationWarnings = checkAutomationEligibility(allTasks, index);
      completenessWarnings.push(...automationWarnings);

      // AC: @config-validation ac-1 — require_acceptance promotes missing AC to errors
      if (options.requireAcceptance) {
        const missingAC = completenessWarnings.filter(
          (w) => w.type === "missing_acceptance_criteria",
        );
        const otherWarnings = completenessWarnings.filter(
          (w) => w.type !== "missing_acceptance_criteria",
        );

        // Promote missing AC warnings to schema errors
        for (const w of missingAC) {
          result.schemaErrors.push({
            file: "completeness",
            path: w.itemRef,
            message: w.message,
          });
        }

        result.completenessWarnings = otherWarnings;
      } else {
        result.completenessWarnings = completenessWarnings;
      }
    }
  }

  // Meta manifest validation (AC-meta-manifest-2, AC-meta-manifest-3)
  const metaManifestPath = await findMetaManifest(ctx.specDir);
  if (metaManifestPath) {
    // Use metaCtx already loaded above
    result.metaStats = {
      agents: metaCtx.agents.length,
      workflows: metaCtx.workflows.length,
      conventions: metaCtx.conventions.length,
      observations: metaCtx.observations.length,
      skills: metaCtx.skills.length,
    };

    // Validate meta manifest schema with strict ULID validation
    if (runSchema) {
      const metaErrors = await validateMetaManifestFile(metaManifestPath);
      // Prefix all meta errors with "meta:"
      for (const err of metaErrors) {
        err.path = err.path ? `meta:${err.path}` : "meta:";
      }
      result.schemaErrors.push(...metaErrors);
      result.stats.filesChecked++;

      // AC: @skill-content-model ac-3 - validate skill content files exist
      if (metaCtx.skills.length > 0) {
        const skillContentErrors = await validateSkillContentFiles(ctx, metaCtx.skills);
        result.schemaErrors.push(...skillContentErrors);
      }

      // AC: @skill-validation ac-3 - detect orphaned skill directories
      const orphanedSkillWarnings = await findOrphanedSkillDirectories(ctx, metaCtx.skills);
      result.refWarnings.push(...orphanedSkillWarnings);
    }
  }

  // Set valid flag
  result.valid =
    result.schemaErrors.length === 0 &&
    result.refErrors.length === 0 &&
    result.traitCycleErrors.length === 0;

  return result;
}

import * as path from "node:path";
import chalk from "chalk";
import type { Command } from "commander";
import type { LoadedSpecItem, LoadedTask } from "../../parser/index.js";
import {
  AlignmentIndex,
  type AlignmentWarning,
  checkACSchemaReferences,
  type CompletenessWarning,
  type ConventionValidationResult,
  expandIncludePattern,
  type FixResult,
  findTaskFiles,
  fixFiles,
  initContext,
  loadAllItems,
  loadAllTasks,
  loadMetaContext,
  ReferenceIndex,
  type ValidationResult,
  validate,
  validateConventions,
} from "../../parser/index.js";
import {
  type SkillValidationResult,
  validateSkills,
} from "../../parser/validate-skills.js";
import { validation as validationStrings } from "../../strings/index.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output } from "../output.js";

/**
 * Staleness warning types
 * AC: @stale-status-detection
 */
interface StalenessWarning {
  type:
    | "parent-pending-children-done"
    | "spec-implemented-no-task"
    | "task-done-spec-not-started"
    | "automation-blocking";
  message: string;
  refs: string[];
}

/**
 * Check for stale status mismatches between specs and tasks
 * AC: @stale-status-detection ac-1, ac-2, ac-3
 */
function checkStaleness(
  items: LoadedSpecItem[],
  tasks: LoadedTask[],
  refIndex: ReferenceIndex,
): StalenessWarning[] {
  const warnings: StalenessWarning[] = [];

  // AC: @stale-status-detection ac-1 (parent-pending-children-done)
  // Check if task with dependencies is pending but all dependencies are completed
  for (const task of tasks) {
    // Only check pending/in_progress tasks with dependencies
    if (task.status !== "pending" && task.status !== "in_progress") continue;
    if (!task.depends_on || task.depends_on.length === 0) continue;

    // Resolve all dependency tasks
    const depTasks = task.depends_on
      .map((depRef) => {
        const result = refIndex.resolve(depRef);
        if (!result.ok) return null;
        return tasks.find((t) => t._ulid === result.ulid);
      })
      .filter((t): t is LoadedTask => t !== null);

    if (depTasks.length === 0) continue;

    // Check if all dependencies are completed and their linked specs are implemented
    const allDepsDone = depTasks.every((depTask) => {
      if (depTask.status !== "completed") return false;

      // If the dep task has a spec_ref, check if that spec is implemented
      if (depTask.spec_ref) {
        const result = refIndex.resolve(depTask.spec_ref);
        if (!result.ok) return true; // Missing spec ref doesn't block
        const spec = items.find((item) => item._ulid === result.ulid);
        return spec?.status?.implementation === "implemented";
      }
      return true;
    });

    if (allDepsDone) {
      const taskRef = task.slugs[0] || refIndex.shortUlid(task._ulid);
      warnings.push({
        type: "parent-pending-children-done",
        message: `Task @${taskRef} is ${task.status} but all dependencies are completed. Consider completing or reviewing.`,
        refs: [task._ulid],
      });
    }
  }

  // AC: @stale-status-detection ac-2 (spec-implemented-no-task)
  // Check if spec is implemented but has no completed tasks
  for (const item of items) {
    if (item.status?.implementation !== "implemented") continue;

    // AC: @trait-retrospective ac-1
    // Skip retrospective specs from staleness warnings
    const isRetrospective = item.traits?.includes("@trait-retrospective");
    if (isRetrospective) continue;

    // Find completed tasks that reference this spec
    const completedTasks = tasks.filter((task) => {
      if (task.status !== "completed" || !task.spec_ref) return false;
      const result = refIndex.resolve(task.spec_ref);
      return result.ok && result.ulid === item._ulid;
    });

    if (completedTasks.length === 0) {
      const specRef = item.slugs[0] || refIndex.shortUlid(item._ulid);
      warnings.push({
        type: "spec-implemented-no-task",
        message: `Spec @${specRef} is implemented but has no completed tasks. Verify implementation or link existing task.`,
        refs: [item._ulid],
      });
    }
  }

  // AC: @stale-status-detection ac-3 (task-done-spec-not-started)
  // Check if task is completed but spec is still not_started
  for (const task of tasks) {
    if (task.status !== "completed") continue;
    if (!task.spec_ref) continue;

    // Resolve spec reference
    const result = refIndex.resolve(task.spec_ref);
    if (!result.ok) continue;

    const spec = items.find((item) => item._ulid === result.ulid);
    if (!spec) continue;

    if (spec.status?.implementation === "not_started") {
      const taskRef = task.slugs[0] || refIndex.shortUlid(task._ulid);
      const specRef = spec.slugs[0] || refIndex.shortUlid(spec._ulid);
      warnings.push({
        type: "task-done-spec-not-started",
        message: `Task @${taskRef} completed but spec @${specRef} is not_started. Update spec status.`,
        refs: [task._ulid, spec._ulid],
      });
    }
  }

  // AC: @validation ac-1
  // Check for manual_only parents blocking eligible children
  for (const parentTask of tasks) {
    if (parentTask.automation !== "manual_only") continue;

    // Find tasks that depend on this parent
    const dependentTasks = tasks.filter((t) =>
      t.depends_on?.some((depRef) => {
        const result = refIndex.resolve(depRef);
        return result.ok && result.ulid === parentTask._ulid;
      }),
    );

    // Filter for eligible children
    const eligibleChildren = dependentTasks.filter(
      (t) => t.automation === "eligible",
    );

    if (eligibleChildren.length > 0) {
      const parentRef =
        parentTask.slugs[0] || refIndex.shortUlid(parentTask._ulid);
      const childRefs = eligibleChildren.map(
        (c) => `@${c.slugs[0] || refIndex.shortUlid(c._ulid)}`,
      );

      warnings.push({
        type: "automation-blocking",
        message: `Task @${parentRef} is manual_only and blocks ${eligibleChildren.length} eligible child task(s): ${childRefs.join(", ")}`,
        refs: [parentTask._ulid, ...eligibleChildren.map((c) => c._ulid)],
      });
    }
  }

  return warnings;
}

/**
 * Format staleness warnings for display
 * AC: @stale-status-detection ac-4
 */
function formatStalenessWarnings(
  warnings: StalenessWarning[],
  verbose: boolean,
): void {
  if (warnings.length === 0) {
    console.log(chalk.green("Staleness: OK"));
    return;
  }

  console.log(chalk.yellow(`\nStaleness warnings: ${warnings.length}`));

  // Group by type
  const parentPending = warnings.filter(
    (w) => w.type === "parent-pending-children-done",
  );
  const specNoTask = warnings.filter(
    (w) => w.type === "spec-implemented-no-task",
  );
  const taskDoneSpecNot = warnings.filter(
    (w) => w.type === "task-done-spec-not-started",
  );
  const automationBlocking = warnings.filter(
    (w) => w.type === "automation-blocking",
  );

  if (parentPending.length > 0) {
    console.log(
      chalk.yellow(`  Parent pending, children done: ${parentPending.length}`),
    );
    const shown = verbose ? parentPending : parentPending.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && parentPending.length > 3) {
      console.log(chalk.gray(`    ... and ${parentPending.length - 3} more`));
    }
  }

  if (specNoTask.length > 0) {
    console.log(
      chalk.yellow(`  Spec implemented, no task: ${specNoTask.length}`),
    );
    const shown = verbose ? specNoTask : specNoTask.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && specNoTask.length > 3) {
      console.log(chalk.gray(`    ... and ${specNoTask.length - 3} more`));
    }
  }

  if (taskDoneSpecNot.length > 0) {
    console.log(
      chalk.yellow(`  Task done, spec not started: ${taskDoneSpecNot.length}`),
    );
    const shown = verbose ? taskDoneSpecNot : taskDoneSpecNot.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && taskDoneSpecNot.length > 3) {
      console.log(chalk.gray(`    ... and ${taskDoneSpecNot.length - 3} more`));
    }
  }

  if (automationBlocking.length > 0) {
    console.log(
      chalk.yellow(`  Automation blocking: ${automationBlocking.length}`),
    );
    const shown = verbose ? automationBlocking : automationBlocking.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && automationBlocking.length > 3) {
      console.log(
        chalk.gray(`    ... and ${automationBlocking.length - 3} more`),
      );
    }
  }
}

/**
 * AC schema drift warning type
 */
interface ACDriftWarning {
  type: "ac_schema_field_mismatch";
  itemRef: string;
  itemTitle: string;
  message: string;
  details?: string;
}

/**
 * Format AC schema drift warnings for display
 */
function formatDriftWarnings(
  warnings: CompletenessWarning[],
  verbose: boolean,
): void {
  // Filter to only drift warnings
  const driftWarnings = warnings.filter(
    (w) => w.type === "ac_schema_field_mismatch",
  ) as ACDriftWarning[];

  if (driftWarnings.length === 0) {
    console.log(chalk.green("AC Schema Drift: OK"));
    return;
  }

  console.log(chalk.yellow(`\nAC Schema Drift warnings: ${driftWarnings.length}`));

  // Group by item
  const byItem = new Map<string, ACDriftWarning[]>();
  for (const w of driftWarnings) {
    const existing = byItem.get(w.itemRef) || [];
    existing.push(w);
    byItem.set(w.itemRef, existing);
  }

  const itemEntries = [...byItem.entries()];
  const shown = verbose ? itemEntries : itemEntries.slice(0, 5);

  for (const [itemRef, itemWarnings] of shown) {
    const firstWarning = itemWarnings[0];
    console.log(chalk.yellow(`  ${itemRef} - ${firstWarning.itemTitle}`));
    for (const w of itemWarnings) {
      console.log(chalk.yellow(`    ! ${w.message}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
  }

  if (!verbose && itemEntries.length > 5) {
    console.log(
      chalk.gray(`  ... and ${itemEntries.length - 5} more items with drift`),
    );
  }
}

/**
 * Format convention validation results for display
 * AC: @convention-definitions ac-3, ac-4
 */
function formatConventionValidationResult(
  result: ConventionValidationResult,
): void {
  if (result.valid && result.skipped.length === 0) {
    console.log(chalk.green("Conventions: OK"));
    return;
  }

  // AC: @convention-definitions ac-4
  // Skipped prose conventions
  if (result.skipped.length > 0) {
    for (const domain of result.skipped) {
      console.log(chalk.gray(`ℹ Skipping prose convention: ${domain}`));
    }
  }

  // AC: @convention-definitions ac-3
  // Validation errors
  if (result.errors.length > 0) {
    console.log(chalk.red(`\nConvention violations: ${result.errors.length}`));
    for (const err of result.errors) {
      console.log(chalk.red(`  ✗ ${err.domain}`));
      console.log(chalk.gray(`    ${err.message}`));
      if (err.expected) {
        console.log(chalk.gray(`    Expected: ${err.expected}`));
      }
      if (err.location) {
        console.log(chalk.gray(`    Location: ${err.location}`));
      }
    }
  } else {
    console.log(chalk.green("\nConventions: OK"));
  }

  // Stats
  console.log(
    chalk.gray(`\nConventions checked: ${result.stats.conventionsChecked}`),
  );
  console.log(
    chalk.gray(`Conventions skipped: ${result.stats.conventionsSkipped}`),
  );
}

/**
 * Format skill validation results for display
 */
function formatSkillValidationResult(
  result: SkillValidationResult,
  verbose: boolean,
): void {
  if (result.filesChecked === 0) {
    console.log(chalk.gray("Skills: No skill files found"));
    return;
  }

  if (result.valid) {
    console.log(
      chalk.green(`Skills: OK (${result.filesChecked} files checked)`),
    );
    return;
  }

  console.log(chalk.red(`\nSkill validation errors: ${result.errors.length}`));
  console.log(chalk.gray(`Files checked: ${result.filesChecked}`));

  // Group errors by file
  const errorsByFile = new Map<string, typeof result.errors>();
  for (const err of result.errors) {
    const existing = errorsByFile.get(err.file) || [];
    existing.push(err);
    errorsByFile.set(err.file, existing);
  }

  for (const [file, errors] of errorsByFile.entries()) {
    console.log(chalk.yellow(`\n  ${file}:`));
    const shown = verbose ? errors : errors.slice(0, 5);
    for (const err of shown) {
      const location = err.line ? `:${err.line}` : "";
      console.log(chalk.red(`    ✗ ${err.type}${location}`));
      console.log(chalk.gray(`      ${err.message}`));
    }
    if (!verbose && errors.length > 5) {
      console.log(chalk.gray(`    ... and ${errors.length - 5} more`));
    }
  }
}

/**
 * Format completeness warnings for display
 * AC: @spec-completeness ac-4
 */
function formatCompletenessWarnings(
  warnings: CompletenessWarning[],
  verbose: boolean,
): void {
  if (warnings.length === 0) {
    console.log(chalk.green("Completeness: OK"));
    return;
  }

  console.log(chalk.yellow(`\nCompleteness warnings: ${warnings.length}`));

  // Group by type
  const missingAC = warnings.filter(
    (w) => w.type === "missing_acceptance_criteria",
  );
  const missingDesc = warnings.filter((w) => w.type === "missing_description");
  const statusMismatch = warnings.filter(
    (w) => w.type === "status_inconsistency",
  );
  const missingOwnACCoverage = warnings.filter(
    (w) => w.type === "missing_test_coverage" && w.subtype !== "trait_ac",
  );
  const missingTraitACCoverage = warnings.filter(
    (w) => w.type === "missing_test_coverage" && w.subtype === "trait_ac",
  );
  const automationNoSpec = warnings.filter(
    (w) => w.type === "automation_eligible_no_spec",
  );

  // AC: @spec-completeness ac-4
  // Show summary with counts by issue type
  if (missingAC.length > 0) {
    console.log(
      chalk.yellow(`  Missing acceptance criteria: ${missingAC.length}`),
    );
    const shown = verbose ? missingAC : missingAC.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.gray(`    ○ ${w.itemRef} - ${w.itemTitle}`));
    }
    if (!verbose && missingAC.length > 3) {
      console.log(chalk.gray(`    ... and ${missingAC.length - 3} more`));
    }
  }

  if (missingDesc.length > 0) {
    console.log(chalk.yellow(`  Missing descriptions: ${missingDesc.length}`));
    const shown = verbose ? missingDesc : missingDesc.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.gray(`    ○ ${w.itemRef} - ${w.itemTitle}`));
    }
    if (!verbose && missingDesc.length > 3) {
      console.log(chalk.gray(`    ... and ${missingDesc.length - 3} more`));
    }
  }

  if (statusMismatch.length > 0) {
    console.log(
      chalk.yellow(`  Status inconsistencies: ${statusMismatch.length}`),
    );
    for (const w of statusMismatch) {
      console.log(chalk.yellow(`    ! ${w.message}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
  }

  if (missingOwnACCoverage.length > 0) {
    console.log(
      chalk.yellow(`  Missing own AC coverage: ${missingOwnACCoverage.length}`),
    );
    const shown = verbose
      ? missingOwnACCoverage
      : missingOwnACCoverage.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.itemRef} - ${w.itemTitle}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
    if (!verbose && missingOwnACCoverage.length > 3) {
      console.log(
        chalk.gray(`    ... and ${missingOwnACCoverage.length - 3} more`),
      );
    }
  }

  if (missingTraitACCoverage.length > 0) {
    console.log(
      chalk.yellow(`  Missing trait AC coverage: ${missingTraitACCoverage.length}`),
    );
    const shown = verbose
      ? missingTraitACCoverage
      : missingTraitACCoverage.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.itemRef} - ${w.itemTitle}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
    if (!verbose && missingTraitACCoverage.length > 3) {
      console.log(
        chalk.gray(`    ... and ${missingTraitACCoverage.length - 3} more`),
      );
    }
  }

  // AC: @task-automation-eligibility ac-21, ac-23
  if (automationNoSpec.length > 0) {
    console.log(
      chalk.yellow(`  Automation without spec: ${automationNoSpec.length}`),
    );
    const shown = verbose ? automationNoSpec : automationNoSpec.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.itemRef} - ${w.itemTitle}`));
      console.log(chalk.gray(`      ${w.message}`));
    }
    if (!verbose && automationNoSpec.length > 3) {
      console.log(
        chalk.gray(`    ... and ${automationNoSpec.length - 3} more`),
      );
    }
  }
}

/**
