import { z } from "zod";
import {
  DateTimeSchema,
  ImplementationStatusSchema,
  ItemTypeSchema,
  MaturitySchema,
  PrioritySchema,
  RefSchema,
  SlugSchema,
  UlidSchema,
} from "./common.js";
import { NoteSchema } from "./task.js";

/**
 * Status block for spec items
 */
export const StatusSchema = z.object({
  maturity: MaturitySchema.default("draft"),
  implementation: ImplementationStatusSchema.default("not_started"),
});

/**
 * Acceptance criteria in Given/When/Then format
 */
export const AcceptanceCriterionSchema = z.object({
  id: z.string(),
  given: z.string(),
  when: z.string(),
  then: z.string(),
});

/**
 * Implementation traceability
 */
export const ImplementationRefSchema = z.object({
  path: z.string(),
  function: z.string().optional(),
  lines: z.string().optional(),
});

/**
 * Traceability block
 */
export const TraceabilitySchema = z.object({
  implementation: z.array(ImplementationRefSchema).optional(),
  tests: z.array(z.object({ path: z.string() })).optional(),
  commits: z.array(z.string()).optional(),
  issues: z.array(z.string()).optional(),
});

/**
 * Full spec item schema
 */
export const SpecItemSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: ItemTypeSchema.optional(),

  // Status
  status: StatusSchema.optional(),

  // Classification
  priority: PrioritySchema.optional(),
  tags: z.array(z.string()).default([]),

  // Content
  description: z.string().optional(),
  acceptance_criteria: z.array(AcceptanceCriterionSchema).optional(),

  // Relationships (references start with @)
  depends_on: z.array(RefSchema).default([]),
  implements: z.array(RefSchema).default([]),
  relates_to: z.array(RefSchema).default([]),
  tests: z.array(RefSchema).default([]),
  traits: z.array(RefSchema).default([]),
  supersedes: RefSchema.nullable().optional(),

  // Traceability
  traceability: TraceabilitySchema.optional(),

  // Lifecycle
  created: DateTimeSchema.optional(),
  created_by: z.string().optional(),
  deprecated_in: z.string().nullable().optional(),
  superseded_by: RefSchema.nullable().optional(),

  // Verification metadata (for retrospective specs)
  verified_at: DateTimeSchema.optional(),
  verified_by: RefSchema.optional(),

  // Notes (work log / implementation context)
  notes: z.array(NoteSchema).default([]),
});

/**
 * Spec item input schema (for creating new items, ULID auto-generated)
 */
export const SpecItemInputSchema = SpecItemSchema.omit({ _ulid: true }).extend({
  _ulid: UlidSchema.optional(),
});

/**
 * Spec item patch schema (partial fields, passthrough for unknown)
 * Used by `kspec item patch` for JSON updates
 */
export const SpecItemPatchSchema = SpecItemInputSchema.partial().passthrough();

/**
 * Root manifest schema
 */
export const ManifestSchema = z.object({
  kynetic: z.string().default("1.0"),
  project: z.object({
    name: z.string(),
    version: z.string().default("0.1.0"),
    status: MaturitySchema.default("draft"),
  }),

  // Inline items (small projects)
  modules: z.array(z.any()).optional(), // Recursive, define separately if needed
  features: z.array(z.any()).optional(),
  requirements: z.array(z.any()).optional(),
  constraints: z.array(z.any()).optional(),
  decisions: z.array(z.any()).optional(),
  traits: z.array(z.any()).optional(),

  // External references (large projects)
  includes: z.array(z.string()).optional(),

  // Hooks configuration
  hooks: z.record(z.string()).optional(),

  // AC: @config-manifest-cleanup ac-2 — backward compat for existing manifests with config block
  // This field is DEPRECATED — use kspec.config.yaml instead
  config: z.any().optional(),

  // AC: @config-manifest-cleanup ac-4 — backward compat for existing manifests with daemon block
  // DEPRECATED: Use kspec.config.yaml daemon settings instead
  // Kept as explicit optional for backward compat parsing (do not use .passthrough())
  daemon: z.object({
    auto_start: z.boolean().default(true),
    port: z.number().int().min(1).max(65535).default(3456),
  }).optional(),
});

export type Status = z.infer<typeof StatusSchema>;
export type AcceptanceCriterion = z.infer<typeof AcceptanceCriterionSchema>;
export type ImplementationRef = z.infer<typeof ImplementationRefSchema>;
export type Traceability = z.infer<typeof TraceabilitySchema>;
export type SpecItem = z.infer<typeof SpecItemSchema>;
export type SpecItemInput = z.infer<typeof SpecItemInputSchema>;
export type SpecItemPatch = z.infer<typeof SpecItemPatchSchema>;
export type Manifest = z.infer<typeof ManifestSchema>;

import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  TaskStatusSchema,
  TaskTypeSchema,
  UlidSchema,
  VcsRefSchema,
} from "./common.js";

/**
 * Automation eligibility status for tasks
 * AC: @task-automation-eligibility ac-1
 * - eligible: Task can be processed by automation loops
 * - needs_review: Task was rejected by automation and needs human review
 * - manual_only: Task should only be handled by humans
 * - undefined/absent: Task has not been assessed for automation (unassessed)
 */
export const AutomationStatusSchema = z.enum([
  "eligible",
  "needs_review",
  "manual_only",
]);

/**
 * Note entry - append-only work log
 */
export const NoteSchema = z.object({
  _ulid: UlidSchema,
  created_at: DateTimeSchema,
  author: z.string().optional(),
  content: z.string(),
  supersedes: UlidSchema.nullable().optional(),
});

/**
 * Todo item - lightweight checklist
 */
export const TodoSchema = z.object({
  id: z.number().int().positive(),
  text: z.string(),
  done: z.boolean().default(false),
  done_at: DateTimeSchema.optional(),
  added_at: DateTimeSchema,
  added_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Full task schema
 * Note: created_at defaults to now if not provided (auto-populated on load)
 */
export const TaskSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.default("task"),

  // Content (doesn't duplicate spec - brief description for standalone context)
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship (links to workflow, agent, or convention for process improvement tracking)
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship (links to the plan this task was derived from)
  // AC: @plan-derive ac-5, ac-6
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking (where this task came from)
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.default("pending"),
  blocked_by: z.array(z.string()).default([]),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).default([]),
  context: z.array(RefSchema).default([]),

  // Work metadata
  priority: z.number().int().min(1).max(5).default(3),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).default([]),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).default([]),

  // Session scoping (advisory, not enforced)
  // AC: @session-scoped-task-claiming ac-schema
  session_id: z.string().nullable().optional(),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  started_at: DateTimeSchema.nullable().optional(),
  submitted_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).default([]),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).default([]),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2)
  // Optional - absent means unassessed
  automation: AutomationStatusSchema.optional(),
});

/**
 * Task input schema (for creating new tasks, some fields auto-generated)
 * All fields except title are optional - defaults will be applied
 */
export const TaskInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.optional(),

  // Content
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.optional(),
  blocked_by: z.array(z.string()).optional(),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).optional(),
  context: z.array(RefSchema).optional(),

  // Work metadata
  priority: z.number().int().min(1).max(5).optional(),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).optional(),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).optional(),

  // Session scoping
  session_id: z.string().nullable().optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  started_at: DateTimeSchema.nullable().optional(),
  submitted_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).optional(),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).optional(),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2, ac-13)
  automation: AutomationStatusSchema.optional(),
});

/**
 * Tasks file schema (collection of tasks)
 */
export const TasksFileSchema = z.object({
  kynetic_tasks: z.string().default("1.0"),
  tasks: z.array(TaskSchema),
});

export type Note = z.infer<typeof NoteSchema>;
export type Todo = z.infer<typeof TodoSchema>;
export type Task = z.infer<typeof TaskSchema>;
export type TaskInput = z.infer<typeof TaskInputSchema>;
export type TasksFile = z.infer<typeof TasksFileSchema>;

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  cleanupTempDir,
  createTempDir,
  initGitRepo,
  kspecOutput as kspec,
  kspecWithStatus,
} from "./helpers/cli";

/**
 * Tests for AC schema field drift detection
 * Task: @01KGGZKQ
 *
 * Validates that acceptance criteria don't reference schema fields that don't exist.
 */
describe("AC Schema Drift detection", () => {
  let tmpDir: string;

  beforeEach(async () => {
    tmpDir = await createTempDir("kspec-drift-test-");
    initGitRepo(tmpDir);
  });

  afterEach(async () => {
    if (tmpDir) {
      await cleanupTempDir(tmpDir);
    }
  });

  it("should warn when AC references non-existent field like item.children", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references children field (doesn't exist in schema)
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a parent item with children
      when: the item.children are modified
      then: all item.children should be updated
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift warnings");
    expect(result).toContain("item.children");
    expect(result).toContain("parse-time/conceptual field");
  });

  it("should warn when AC references spec_ref.field (spec_ref is a string, not object)", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references spec_ref.children
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with ref drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a task with a spec_ref
      when: the spec_ref.status changes
      then: the task should reflect spec_ref.children state
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift warnings");
    expect(result).toContain("spec_ref");
    expect(result).toContain("reference string, not an object");
  });

  it("should NOT warn when AC references valid schema fields", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references valid fields
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with valid refs
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a spec item
      when: the item.status is updated
      then: the item.tags should reflect the change
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift: OK");
    expect(result).not.toContain("AC Schema Drift warnings");
  });

  it("should warn when AC references task fields that don't exist", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references unknown task field
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with task drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a task
      when: the task.foobar changes
      then: task.baz should be updated
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift warnings");
    expect(result).toContain("task.foobar");
    expect(result).toContain("not a known schema field");
  });

  it("should accept valid status.maturity and status.implementation references", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references status fields
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with status refs
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a spec item
      when: status.maturity is updated
      then: status.implementation should be validated
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift: OK");
  });

  it("should only run drift checks when --drift flag is provided", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC that references children field
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a parent item
      when: item.children are modified
      then: item.children should be updated
`,
    );

    // Run validate WITHOUT --drift flag
    const resultWithoutFlag = kspec("validate", tmpDir);

    // Should NOT contain drift warnings
    expect(resultWithoutFlag).not.toContain("AC Schema Drift");

    // Run validate WITH --drift flag
    const resultWithFlag = kspec("validate --drift", tmpDir);

    // Should contain drift warnings
    expect(resultWithFlag).toContain("AC Schema Drift");
    // Scoped mode should not run unrelated warning checks
    expect(resultWithFlag).not.toContain("Alignment warnings");
    expect(resultWithFlag).not.toContain("Completeness warnings");
    expect(resultWithFlag).not.toContain("Staleness warnings");
  });

  it("should exit with code 6 for warnings, code 4 with --strict", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with AC drift issue
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: a parent item
      when: item.children are modified
      then: item.children should be updated
`,
    );

    // Run validate --drift (without --strict) - should exit 6 (warnings present)
    const resultNoStrict = kspecWithStatus("validate --drift", tmpDir);
    expect(resultNoStrict.exitCode).toBe(6); // VALIDATION_WARNINGS

    // Run validate --drift --strict - should exit 4 (warnings treated as errors)
    const resultStrict = kspecWithStatus("validate --drift --strict", tmpDir);
    expect(resultStrict.exitCode).toBe(4); // VALIDATION_FAILED
  });

  it("should report multiple drift issues in the same AC", async () => {
    const specDir = path.join(tmpDir, "spec");
    await fs.mkdir(specDir);

    // Create manifest
    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: test-project
  version: 0.1.0
includes:
  - "spec/module.yaml"
`,
    );

    // Create spec with multiple drift issues
    await fs.writeFile(
      path.join(specDir, "module.yaml"),
      `- _ulid: 01JHNKAB01SPEC0000000000A1
  slugs:
    - test-spec
  title: Test Spec with multiple drift
  type: feature
  acceptance_criteria:
    - id: ac-1
      given: an item with item.children and spec_ref.status
      when: item.parent changes
      then: spec_ref.children should cascade to item.children
`,
    );

    // Run validate --drift
    const result = kspec("validate --drift", tmpDir);

    expect(result).toContain("AC Schema Drift warnings");
